<?php $root='../';$title='Pengajuan';include '../includes/header.php';$msg='';
$l=row('SELECT * FROM layanan WHERE id=?',[(int)($_GET['id']??0)]);if(!$l){echo "<div class='container mt-5'>Layanan tidak ditemukan. <a href='layanan.php'>Kembali</a></div>";include '../includes/footer.php';exit;}
if($_SERVER['REQUEST_METHOD']=='POST'){try{if(!csrf_ok())throw new Exception('Sesi tidak valid');if(!preg_match('/^\d{16}$/',$_POST['nik']))throw new Exception('NIK harus 16 digit');if(trim($_POST['nama'])=='')throw new Exception('Nama wajib diisi');
$f=upload('file');$no='LYN-'.date('Ymd').'-'.random_int(1000,9999);
run('INSERT INTO pengajuan_layanan(nomor,layanan_id,nama,nik,hp,alamat,keperluan,file)VALUES(?,?,?,?,?,?,?,?)',[$no,$l['id'],$_POST['nama'],$_POST['nik'],$_POST['hp'],$_POST['alamat'],$_POST['keperluan'],$f]);
$msg="<div class='alert alert-success'>Permohonan terkirim. Nomor Pengajuan: <b>$no</b> (simpan untuk cek status)</div>";}catch(Exception $x){$msg="<div class='alert alert-danger'>".e($x->getMessage())."</div>";}}?>
<div class="container" style="max-width:700px"><h2 class="judul"><?=e($l['nama'])?></h2><?=$msg?><form method="post" enctype="multipart/form-data" class="card-desa bg-white p-4"><?=csrf()?><input name="nama" class="form-control mb-2" placeholder="Nama lengkap" required><input name="nik" class="form-control mb-2" placeholder="NIK (16 digit)" maxlength="16" required><input name="hp" class="form-control mb-2" placeholder="Nomor HP"><textarea name="alamat" class="form-control mb-2" placeholder="Alamat"></textarea><textarea name="keperluan" class="form-control mb-2" placeholder="Keperluan" required></textarea><label class="small">Upload dokumen (jpg/png/pdf, maks 5MB)</label><input type="file" name="file" class="form-control mb-3"><button class="btn btn-hijau">Kirim Permohonan</button></form></div><?php include '../includes/footer.php';?>
